INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_MODERN_CATHOLIC','Modern Catholicism (19th–21st c.)',1800,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_THERESE_SOUL','primary text','Thérèse of Lisieux, Story of a Soul (1898)','Christian'),
 ('SRC_FAUSTINA_DIARY','primary text','Faustina Kowalska, Diary: Divine Mercy in My Soul (1930s)','Christian'),
 ('SRC_FATIMA_MEMOIRS','primary text','Lúcia dos Santos, Fátima in Lúcia''s Own Words (Memoirs)','Christian')
INSERT INTO _e VALUES
 ('ENT_MOC_OL_LOURDES','Our Lady of Lourdes','Marian apparition','Marian apparition','Christian','Marian devotion; healing','B','Marian apparitions to Bernadette Soubirous at the grotto of Massabielle, Lourdes, France, 1858; major healing pilgrimage shrine. Self-identification ''I am the Immaculate Conception.'''),
 ('ENT_MOC_OL_FATIMA','Our Lady of Fátima','Marian apparition','Marian apparition','Christian','Marian devotion; prophecy','B','Marian apparitions to three shepherd children at Fátima, Portugal, 1917; associated with the ''three secrets'' and the Miracle of the Sun.'),
 ('ENT_MOC_MIRACULOUS_MEDAL','Our Lady of the Miraculous Medal','Marian apparition','Marian apparition','Christian','Marian devotion; sacramental','B','Apparition to Catherine Labouré at the Rue du Bac convent chapel, Paris, 1830; origin of the Miraculous Medal devotion.'),
 ('ENT_MOC_OL_LA_SALETTE','Our Lady of La Salette','Marian apparition','Marian apparition','Christian','Marian devotion; penance','B','Apparition to Maximin Giraud and Mélanie Calvat at La Salette, French Alps, 1846; a weeping Madonna calling for conversion.'),
 ('ENT_MOC_OL_KNOCK','Our Lady of Knock','Marian apparition','Marian apparition','Christian','Marian devotion','B','Silent apparition of Mary, Joseph, John the Evangelist and the Lamb on the Altar at Knock, County Mayo, Ireland, 1879.'),
 ('ENT_MOC_OL_BEAURAING','Our Lady of Beauraing','Marian apparition','Marian apparition','Christian','Marian devotion','C','Apparitions (''the Virgin with the Golden Heart'') to five children at Beauraing, Belgium, 1932–33; ecclesiastically approved.'),
 ('ENT_MOC_OL_BANNEUX','Our Lady of Banneux','Marian apparition','Marian apparition','Christian','Marian devotion; healing','C','Apparitions (''the Virgin of the Poor'') to Mariette Beco at Banneux, Belgium, 1933; spring associated with healing.'),
 ('ENT_MOC_THERESE_LISIEUX','Thérèse of Lisieux','Saint','Mystic/saint','Christian','Contemplative spirituality; the ''Little Way''','A','Carmelite nun (1873–1897), ''the Little Flower''; Doctor of the Church; author of Story of a Soul; patron of missions.'),
 ('ENT_MOC_BERNADETTE','Bernadette Soubirous','Saint','Mystic/saint','Christian','Marian visionary','A','French peasant girl and later Sister Marie-Bernarde (1844–1879); visionary of the Lourdes apparitions, 1858.'),
 ('ENT_MOC_JOHN_VIANNEY','John Vianney','Saint','Modern saint','Christian','Parish priesthood; confession','A','The Curé d''Ars (1786–1859); model parish priest and confessor; patron saint of parish priests.'),
 ('ENT_MOC_JOHN_BOSCO','John Bosco','Saint','Modern saint','Christian','Education of youth; founder of the Salesians','A','Italian priest (1815–1888); founded the Salesians of Don Bosco; patron of young people and educators.'),
 ('ENT_MOC_PADRE_PIO','Pio of Pietrelcina','Saint','Mystic/saint','Christian','Stigmata; confession','A','Padre Pio (1887–1968), Capuchin friar reported to bear the stigmata; renowned confessor.'),
 ('ENT_MOC_FAUSTINA','Faustina Kowalska','Saint','Mystic/saint','Christian','Divine Mercy devotion','A','Polish nun (1905–1938), ''Apostle of Divine Mercy''; her Diary inspired the Divine Mercy devotion and feast.'),
 ('ENT_MOC_DAMIEN','Damien of Molokai','Saint','Missionary saint','Christian','Care of lepers; mission','A','Belgian priest (1840–1889) of the Sacred Hearts; served the leper colony of Molokai, Hawaii, and died of leprosy.'),
 ('ENT_MOC_CABRINI','Frances Xavier Cabrini','Saint','Missionary saint','Christian','Care of immigrants; mission','A','Italian-American religious (1850–1917), founder of the Missionary Sisters of the Sacred Heart; first U.S. citizen canonized; patron of immigrants.'),
 ('ENT_MOC_DREXEL','Katharine Drexel','Saint','Missionary saint','Christian','Education; service to Black and Native Americans','A','American heiress and religious (1858–1955); founded the Sisters of the Blessed Sacrament for Indians and Colored People.'),
 ('ENT_MOC_SETON','Elizabeth Ann Seton','Saint','Modern saint','Christian','Catholic education; charity','A','American convert and religious (1774–1821); founder of the Sisters of Charity and the U.S. parochial school system; first native-born U.S. saint.'),
 ('ENT_MOC_GEMMA_GALGANI','Gemma Galgani','Saint','Mystic/saint','Christian','Mysticism; stigmata','B','Italian mystic (1878–1903), ''the Daughter of Passion''; reported stigmata and ecstasies.'),
 ('ENT_MOC_LOUIS_MARTIN','Louis Martin','Saint','Modern saint','Christian','Lay sanctity; Christian marriage','B','French watchmaker (1823–1894), father of Thérèse of Lisieux; canonized 2015 with his wife Zélie.'),
 ('ENT_MOC_ZELIE_MARTIN','Zélie Martin','Saint','Modern saint','Christian','Lay sanctity; Christian marriage','B','French lacemaker (1831–1877), mother of Thérèse of Lisieux; canonized 2015 with her husband Louis.'),
 ('ENT_MOC_TERESA_CALCUTTA','Teresa of Calcutta','Saint','Missionary saint','Christian','Care of the destitute; mission','A','Mother Teresa (1910–1997), Albanian-Indian religious; founder of the Missionaries of Charity. Distinct from the 16th-c. Teresa of Ávila (ENT_EMC_TERESA_AVILA).'),
 ('ENT_MOC_JOHN_PAUL_II','John Paul II','Saint','Modern saint','Christian','Papacy; the new evangelization','A','Karol Wojtyła (1920–2005), Polish pope 1978–2005; canonized 2014; promoted the Divine Mercy devotion.'),
 ('ENT_MOC_JOHN_XXIII','John XXIII','Saint','Modern saint','Christian','Papacy; conciliar reform','A','Angelo Roncalli (1881–1963), ''the Good Pope''; convened the Second Vatican Council; canonized 2014.'),
 ('ENT_MOC_EDITH_STEIN','Edith Stein','Saint','Mystic/saint','Christian','Philosophy; martyrdom','A','Teresa Benedicta of the Cross (1891–1942); Jewish-born philosopher and Carmelite nun killed at Auschwitz; martyr and co-patron of Europe.'),
 ('ENT_MOC_ROMERO','Óscar Romero','Saint','Modern saint','Christian','Social justice; martyrdom','A','Archbishop of San Salvador (1917–1980); martyred at the altar; voice for the poor; canonized 2018.'),
 ('ENT_MOC_SERRA','Junípero Serra','Saint','Missionary saint','Christian','Mission; founding of the California missions','B','Spanish Franciscan missionary (1713–1784); founded the first California missions; canonized 2015.'),
 ('ENT_MOC_GIANNA_MOLLA','Gianna Beretta Molla','Saint','Modern saint','Christian','Lay sanctity; motherhood','B','Italian physician and mother (1922–1962); declined treatment to protect her unborn child; canonized 2004; patron of mothers.'),
 ('ENT_MOC_FRASSATI','Pier Giorgio Frassati','Saint','Modern saint','Christian','Lay sanctity; charity; youth','B','Italian layman (1901–1925), ''the Man of the Beatitudes''; mountaineer and social activist; beatified 1990.'),
 ('ENT_MOC_SOLANUS_CASEY','Solanus Casey','Saint','Modern saint','Christian','Humility; intercessory ministry','B','American Capuchin friar (1870–1957); porter and counselor known for healings; beatified 2017.'),
 ('ENT_MOC_FATIMA_SEERS','The Seers of Fátima','Collective','Marian visionaries','Christian','Marian visionaries','B','Collective hub for the three shepherd children who witnessed the Fátima apparitions of 1917: Lúcia, Francisco and Jacinta.'),
 ('ENT_MOC_LUCIA_SANTOS','Lúcia dos Santos','Saint','Marian visionary','Christian','Marian visionary','B','Eldest Fátima seer (1907–2005); later a Carmelite nun (Sister Lúcia); author of the Fátima Memoirs.'),
 ('ENT_MOC_FRANCISCO_MARTO','Francisco Marto','Saint','Marian visionary','Christian','Marian visionary','B','Fátima seer (1908–1919); died young; canonized with his sister Jacinta in 2017.'),
 ('ENT_MOC_JACINTA_MARTO','Jacinta Marto','Saint','Marian visionary','Christian','Marian visionary','B','Youngest Fátima seer (1910–1920); died young; canonized with her brother Francisco in 2017.'),
 ('ENT_MOC_MARIAN_APPARITIONS','Modern Marian Apparitions','Collective','Marian apparition','Christian','Marian devotion','B','Collective hub grouping the approved modern (1800–present) apparitions of the Virgin Mary.');
